-- Remove independently granted anonymous column privileges as well.
DO $columns$ DECLARE v record; cols text; BEGIN
 FOR v IN SELECT c.oid,c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='public' AND c.relname IN ('unified_patient_view','mis_today_collection_by_user','mis_today_collection_by_dept','mis_today_hourly_collection','hrms_v_workforce_summary','hrms_v_department_workforce','hrms_v_branch_workforce','hrms_v_attrition_monthly','hrms_v_doctor_activity','hrms_v_therapist_activity','hrms_v_expiring_documents','hrms_v_expiring_registrations','hrms_v_probation_ending','hrms_v_expiring_training_certs','unified_patient_directory','mis_daily_revenue','mis_department_revenue','mis_doctor_revenue','mis_opd_summary') LOOP
  SELECT string_agg(quote_ident(a.attname),', ' ORDER BY a.attnum) INTO cols FROM pg_attribute a WHERE a.attrelid=v.oid AND a.attnum>0 AND NOT a.attisdropped;
  EXECUTE format('REVOKE SELECT (%s) ON public.%I FROM PUBLIC,anon',cols,v.relname);
 END LOOP;
END $columns$;
